// Telegram rechaza Markdown desbalanceado. Limpiamos formato y escapamos HTML para parse_mode HTML.
const raw = $json.output || $json.text || '';
let texto = String(raw)
  .replace(/```[a-z]*\n?/gi, '')
  .replace(/```/g, '')
  .replace(/[*`~#>\[\]]/g, '')
  .trim();
// Escapar caracteres especiales de HTML
texto = texto.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { texto: texto || 'No pude generar una respuesta, intenta de nuevo.' } }];

