// Descuenta la franja usada y calcula cuantas franjas Libre le quedan al tutor.
const tutoria = $('Nueva Tutoria Registrada').first().json;
const tutor = $('Leer Datos Tutor').first().json || {};
const franjas = $input.all().map(i => i.json).filter(f => f.id_dispo);

// dia_semana en la hoja: 1 = Lunes ... 7 = Domingo
const dia = ((new Date(tutoria.fecha + 'T00:00:00').getDay() + 6) % 7) + 1;
const hora = String(tutoria.hora || '').trim();
const libres = franjas.filter(f => String(f.estado).trim().toLowerCase() === 'libre');

// La franja que se consumio: misma jornada y misma hora de inicio.
const ocupada = libres.find(f => String(f.dia_semana).trim() === String(dia)
  && String(f.hora_inicio).trim() === hora)
  || libres.find(f => String(f.dia_semana).trim() === String(dia));

const restantes = libres.filter(f => !ocupada || f.id_dispo !== ocupada.id_dispo);

return [{
  json: {
    id_tutoria: tutoria.id_tutoria || '',
    id_tutor: tutoria.id_tutor || '',
    nombre_tutor: tutor.nombre || tutoria.id_tutor || 'sin nombre',
    id_dispo: ocupada ? ocupada.id_dispo : '',
    libres_restantes: restantes.length,
    critico: restantes.length <= 1,
    sin_disponibilidad: restantes.length === 0,
  },
}];
